def _resolve_callable(call: Callable[..., Any]) -> Callable[..., Any]:
    """Recursively unwraps callables (decorators, partial, etc.) to find the base function."""
    while True:
        # Handle standard decorators
        if hasattr(call, '__wrapped__') and call.__wrapped__ is not None:
            call = call.__wrapped__
        # Handle functools.partial
        elif isinstance(call, functools.partial):
            if hasattr(call, 'func'):
                call = call.func
            else:
                # Should not happen for a valid partial
                break
        else:
            break
    return call

def get_typed_signature(call: Callable[..., Any]) -> inspect.Signature:
    resolved_call = _resolve_callable(call)
    signature = inspect.signature(resolved_call)
    globalns = getattr(resolved_call, "__globals__", {})
    typed_params = [
        inspect.Parameter(
            name=param.name,
            kind=param.kind,
            default=param.default,
            annotation=get_typed_annotation(param.annotation, globalns),
        )
        for param in signature.parameters.values()
    ]
    typed_signature = inspect.Signature(typed_params)
    return typed_signature
